        .sender_comp_id = "aaaaaaaaaaaaaaaaaaaa",
        .target_comp_id = "aaaaaaaaaaaaaaaaaaaa",
        .heart_btint = -123456,
        .password = "aaaaaaaaaaaaaaaa",
        .default_appl_ver_id = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
